arguments.command:
cd /workspace && python3 - <<'PYEOF'
p='src/image.cpp'
s=open(p).read()
s = s.replace("""    uint64_t local_count = 0;
    uint64_t subtree = 0;""","""    uint64_t local_count = 0;
    uint64_t subtree = 0;
    int bulk_stage = 0;""")
s = s.replace("""    node.bulk_slot = bulk_slot;
    node.bmp = static_cast<uint32_t>(field(row, rec + 3, 22));""","""    node.bulk_slot = bulk_slot;
    node.bmp = static_cast<uint32_t>(field(row, rec + 3, 22));
    node.bulk_stage = bulk_stage;""")
# bulk_stage must be known before the node is created: move the declaration up
s = s.replace("""    VNode node;
    node.type = static_cast<int>(type);""","""    VNode node;
    node.type = static_cast<int>(type);""")
open(p,'w').write(s)
PYEOF
grep -n "bulk_stage" src/image.cpp
